namespace muestras {
    inline constexpr std::size_t capacidad = 3;
    inline std::array<int, capacidad> datos{};
    inline std::size_t usados = 0;
    bool agregar(int valor);
    std::size_t cantidadActual();
    int sumaActual();
}

#endif

#include "muestras.hpp"

namespace muestras {
    bool agregar(int valor) {
        if (valor < 0 || valor > 9 || usados >= capacidad) {
            return false;
        }
        datos[usados] = valor;
        usados += 1;
        return true;
    }
}

#include "muestras.hpp"

namespace muestras {
    std::size_t cantidadActual() {
        return usados;
    }

    int sumaActual() {
        int total = 0;
        for (std::size_t i = 0; i < usados; ++i) {
            total += datos[i];
        }

        return total;
    }
}

